/* Builds the paused GSAP timeline for a reel from window.__REEL (generated by scripts/build.mjs).
   Deterministic: no Math.random / Date.now; all times are snapped to 1/30 s in the cue list. */
(function () {
  const F = 1 / 30;
  window.__buildReel = function (tl, cfg) {
    const $ = (id) => document.getElementById(id);
    const END = cfg.END;
    const IR = { immediateRender: false };

    // 1 · auto-fit long keywords to their max width (fonts are embedded by the compiler)
    document.querySelectorAll(".kw").forEach((el) => {
      const max = parseFloat(el.style.maxWidth) || 1000;
      const fs = parseFloat(el.style.fontSize);
      const w = el.scrollWidth;
      if (w > max) {
        const nfs = (fs * max) / w;
        el.style.fontSize = nfs + "px";
        el.style.top = parseFloat(el.style.top) + (fs - nfs) * 0.62 + "px";
      }
    });

    // 2 · everything centred horizontally starts hidden
    gsap.set(".kw, .cn, .pill", { xPercent: -50 });
    gsap.set(".kw, .cn, .cn .w, .obj, .pill, .badge, .nametag, .counter, .card3d, .bubble, .follow, .ticks, .burst .lf", { autoAlpha: 0 });
    gsap.set(["#sweep", "#flash"], { autoAlpha: 0 });

    // 3 · camera: punch-in + slow push on teacher shots (wrapper, never the <video>)
    const cams = ["#cam-main", "#cam-matte"];
    gsap.set(cams, { scale: 1, transformOrigin: "50% 0%" });
    cfg.teachers.forEach((t) => {
      tl.set(cams, { scale: t.scale[0], transformOrigin: t.origin }, t.start);
      tl.to(cams, { scale: t.scale[1], duration: t.end - t.start - F, ease: "none" }, t.start);
      if (t.end < END - 0.01) tl.set(cams, { scale: 1, transformOrigin: "50% 0%" }, t.end);
    });

    const exit = (el, c) => {
      if (c.out >= END - 0.05) return;
      // seek-safe exit: card only hides (a transform tween here would re-capture rotationY); others shrink-fade
      if (c.type === "card") tl.set(el, { autoAlpha: 0 }, c.out);
      else tl.fromTo(el, { autoAlpha: 1, scale: 1 }, { autoAlpha: 0, scale: 0.92, duration: 0.1, ease: "power2.in", immediateRender: false }, c.out - 0.1);
    };

    cfg.cues.forEach((c) => {
      const el = $(c.id);
      if (c.type === "kw") {
        tl.set(el, { autoAlpha: 1 }, c.t);
        if (c.anim === "drop") {
          tl.fromTo(el.querySelectorAll(".ch"), { y: -110, scaleY: 1.7, autoAlpha: 0, transformOrigin: "50% 0%" },
            { y: 0, scaleY: 1, autoAlpha: 1, duration: 0.36, ease: "expo.out", stagger: F, ...IR }, c.t);
        } else if (c.anim === "slideL" || c.anim === "slideR") {
          const from = (c.anim === "slideL" ? -1 : 1) * (c.t < 0.05 ? 640 : 1300);
          tl.fromTo(el, { x: from, filter: "blur(14px)" }, { x: 0, filter: "blur(0px)", duration: 0.3, ease: "expo.out", ...IR }, c.t);
        } else {
          tl.fromTo(el, { scale: 0.3, autoAlpha: 0 }, { scale: 1, autoAlpha: 1, duration: 0.35, ease: "back.out(1.7)", ...IR }, c.t);
        }
        exit(el, c);
      } else if (c.type === "cn") {
        tl.set(el, { autoAlpha: 1 }, c.t);
        const ws = el.querySelectorAll(".w");
        ws.forEach((w, i) => tl.fromTo(w, { y: 26, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: 0.2, ease: "power2.out", ...IR }, c.times[i]));
        exit(el, c);
      } else if (c.type === "obj") {
        const r = c.rot || 0;
        if (c.anim === "grow") {
          tl.fromTo(el, { scaleY: 0, scaleX: 0.6, rotation: r, autoAlpha: 1, transformOrigin: "50% 100%" }, { scaleY: 1, scaleX: 1, duration: 0.55, ease: "elastic.out(1, 0.55)", ...IR }, c.t);
        } else if (c.anim === "dropBounce") {
          tl.fromTo(el, { y: -520, rotation: r - 20, autoAlpha: 1 }, { y: 0, rotation: r, duration: 0.7, ease: "bounce.out", ...IR }, c.t);
        } else if (c.anim === "spin") {
          tl.fromTo(el, { rotation: -300, scale: 0.2, autoAlpha: 0 }, { rotation: 0, scale: 1, autoAlpha: 1, duration: 0.75, ease: "back.out(1.4)", ...IR }, c.t);
        } else if (c.anim === "pill") {
          tl.fromTo(el, { scale: 0.5, y: 30, autoAlpha: 0 }, { scale: 1, y: 0, autoAlpha: 1, duration: 0.3, ease: "back.out(2)", ...IR }, c.t);
        } else if (c.anim === "badge") {
          tl.fromTo(el, { x: -320, autoAlpha: 0 }, { x: 0, autoAlpha: 1, duration: 0.35, ease: "expo.out", ...IR }, c.t);
        } else if (c.anim === "bubble") {
          tl.fromTo(el, { y: 140, scale: 0.85, autoAlpha: 0 }, { y: 0, scale: 1, autoAlpha: 1, duration: 0.42, ease: "back.out(1.5)", ...IR }, c.t);
          const dots = el.querySelectorAll(".dots i");
          if (dots.length) {
            const reps = Math.max(0, Math.floor((c.out - c.t - 0.5) / 0.6) - 1);
            tl.fromTo(dots, { y: 0 }, { y: -10, duration: 0.15, ease: "sine.inOut", stagger: 0.1, yoyo: true, repeat: 1, ...IR }, c.t + 0.45);
            for (let k = 1; k <= reps; k++) tl.fromTo(dots, { y: 0 }, { y: -10, duration: 0.15, ease: "sine.inOut", stagger: 0.1, yoyo: true, repeat: 1, ...IR }, c.t + 0.45 + k * 0.6);
          }
        } else {
          tl.fromTo(el, { scale: 0, rotation: r - 25, autoAlpha: 0 }, { scale: 1, rotation: r, autoAlpha: 1, duration: 0.4, ease: "back.out(1.8)", ...IR }, c.t);
        }
        exit(el, c);
      } else if (c.type === "counter") {
        const num = el.querySelector(".num"), ring = el.querySelector(".ring"), p = { v: 0 };
        tl.fromTo(el, { scale: 0.4, autoAlpha: 0 }, { scale: 1, autoAlpha: 1, duration: 0.3, ease: "back.out(1.8)", ...IR }, c.t);
        tl.fromTo(p, { v: 0 }, { v: c.to, duration: 0.6, ease: "power1.inOut", ...IR, onUpdate: () => { num.textContent = String(Math.round(p.v)); } }, c.t + 0.05);
        tl.fromTo(ring, { attr: { "stroke-dashoffset": 804.25 } }, { attr: { "stroke-dashoffset": 0 }, duration: 0.6, ease: "power1.inOut", ...IR }, c.t + 0.05);
        tl.fromTo(num, { scale: 1 }, { scale: 1.18, duration: 0.12, yoyo: true, repeat: 1, ease: "power2.out", ...IR }, c.t + 0.65);
        exit(el, c);
      } else if (c.type === "card") {
        tl.fromTo(el, { x: 420, rotation: c.rot + 25, autoAlpha: 0, transformPerspective: 1000 }, { x: 0, rotation: c.rot, autoAlpha: 1, duration: 0.45, ease: "back.out(1.4)", ...IR }, c.t);
        if (c.flip) tl.fromTo(el, { rotationY: 0 }, { rotationY: 180, duration: 0.5, ease: "power2.inOut", ...IR }, c.flip - 0.15);
        exit(el, c);
      } else if (c.type === "ticks") {
        tl.set(el, { autoAlpha: 1 }, c.t);
        tl.fromTo(el.querySelectorAll(".tk"), { scale: 0.3, autoAlpha: 0 }, { scale: 1, autoAlpha: 1, duration: 0.3, ease: "back.out(2)", stagger: 0.12, ...IR }, c.t);
        exit(el, c);
      } else if (c.type === "burst") {
        document.querySelectorAll(".burst .lf").forEach((lf, i) => {
          const a = (i / 14) * Math.PI * 2 + 0.35 * Math.sin(i * 2.1);
          const d = 300 + 160 * Math.abs(Math.sin(i * 1.7 + 0.4));
          tl.fromTo(lf, { x: 0, y: 0, scale: 0.2, rotation: 0, autoAlpha: 1 },
            { x: Math.cos(a) * d * 1.1, y: Math.sin(a) * d * 0.8, scale: 1 + 0.4 * Math.abs(Math.cos(i)), rotation: (i % 2 ? 1 : -1) * (160 + 30 * i), duration: 1.0, ease: "power3.out", ...IR }, c.t);
          tl.to(lf, { autoAlpha: 0, duration: 0.3, ease: "power1.in" }, c.out - 0.3);
        });
      } else if (c.type === "sweep") {
        tl.fromTo("#sweep", { xPercent: -100, autoAlpha: 1 }, { xPercent: 100, duration: c.out - c.t, ease: "power2.inOut", ...IR }, c.t);
        tl.set("#sweep", { autoAlpha: 0 }, c.out);
      }
    });

    // 4 · section flashes: warm leaf-green light leak, cut hidden at the peak
    cfg.flashes.forEach((f) => {
      tl.fromTo("#flash", { autoAlpha: 0, scale: 0.55 }, { autoAlpha: 1, scale: 1.15, duration: 0.2, ease: "power2.in", ...IR }, f - 0.2);
      tl.fromTo("#flash", { autoAlpha: 1, scale: 1.15 }, { autoAlpha: 0, scale: 1.5, duration: 0.27, ease: "power2.out", ...IR }, f);
    });

    tl.to({}, { duration: END }, 0); // Law #11 anchor: timeline fills its slot
    return tl;
  };
})();
